// Generated by scripts/sync-compose.ts from deploy/docker-compose.yml. Do not edit by hand.
export const composeFile = "# ARTEL self-hosted stack. Needs Docker Compose 2.23.1 or later (the Caddy configuration below is inlined).\n#\n#   1. Save this file and .env.example in one directory.\n#   2. cp .env.example .env   and edit it. Replace every __GENERATE_...__ value (openssl rand -hex 32).\n#   3. docker compose up -d   and open ARTEL_PUBLIC_URL (default http://localhost:8088).\n#\n# The first account to sign up becomes the admin; the admin page (default http://localhost:8090) sets the OpenRouter key.\n# Only the __GENERATE_...__ secrets in .env must change; everything else has a working default.\n# The build sections only matter in a clone of the repository: `docker compose build orchestration agent-server`.\n\nname: artel\n\nx-restart: &restart\n  restart: unless-stopped\n\nservices:\n  postgres:\n    <<: *restart\n    # Must be the pgvector image: a Flyway migration runs CREATE EXTENSION vector.\n    image: pgvector/pgvector:pg16\n    environment:\n      POSTGRES_DB: ${DB_NAME:-artel}\n      POSTGRES_USER: ${DB_USERNAME:-artel}\n      POSTGRES_PASSWORD: ${DB_PASSWORD:?set DB_PASSWORD in .env}\n    volumes:\n      - postgres-data:/var/lib/postgresql/data\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -U $${POSTGRES_USER} -d $${POSTGRES_DB}\"]\n      interval: 5s\n      timeout: 5s\n      retries: 20\n\n  redis:\n    <<: *restart\n    # Holds only five-minute SDK login codes, so persistence stays off on purpose.\n    # Valkey, not Redis: current Redis 7.x tags are RSALv2/SSPLv1, which does not fit an AGPL-3.0 release.\n    # It speaks the same protocol, so the service name and REDIS_URL stay as they were.\n    image: valkey/valkey:8.1.10-alpine\n    command: [\"valkey-server\", \"--save\", \"\", \"--appendonly\", \"no\"]\n    healthcheck:\n      test: [\"CMD\", \"valkey-cli\", \"ping\"]\n      interval: 5s\n      timeout: 3s\n      retries: 20\n\n  minio:\n    <<: *restart\n    # Docker Hub no longer serves minio/minio, so the default is the Chainguard build. Override with\n    # ARTEL_MINIO_IMAGE if you mirror another build.\n    image: ${ARTEL_MINIO_IMAGE:-cgr.dev/chainguard/minio:latest}\n    command: [\"server\", \"/data\", \"--console-address\", \":9001\"]\n    environment:\n      MINIO_ROOT_USER: ${ARTEL_S3_ACCESS_KEY:?set ARTEL_S3_ACCESS_KEY in .env}\n      MINIO_ROOT_PASSWORD: ${ARTEL_S3_SECRET_KEY:?set ARTEL_S3_SECRET_KEY in .env}\n    volumes:\n      - minio-data:/data\n    # No published port. Browsers reach MinIO through the proxy on the public origin (see the caddyfile config below),\n    # and the other services reach it over the compose network.\n    expose:\n      - \"9000\"\n\n  minio-init:\n    # Creates the bucket on first start and exits. Safe to run again. The client image has no shell,\n    # so it connects through the MC_HOST_local variable and on-failure restarts cover the wait for MinIO.\n    image: ${ARTEL_MINIO_CLIENT_IMAGE:-cgr.dev/chainguard/minio-client:latest}\n    depends_on:\n      - minio\n    environment:\n      MC_HOST_local: http://${ARTEL_S3_ACCESS_KEY}:${ARTEL_S3_SECRET_KEY}@minio:9000\n    command: [\"mb\", \"--ignore-existing\", \"local/${ARTEL_S3_BUCKET:-artel}\"]\n    restart: on-failure\n\n  orchestration:\n    <<: *restart\n    image: ${ARTEL_ORCHESTRATION_IMAGE:-ghcr.io/project-artel/orchestration:develop}\n    build:\n      context: ../artel-orchestration-server\n      dockerfile: ../deploy/Dockerfile.orchestration\n    depends_on:\n      postgres:\n        condition: service_healthy\n      redis:\n        condition: service_healthy\n      minio-init:\n        condition: service_completed_successfully\n    environment:\n      DB_HOST: postgres\n      DB_PORT: \"5432\"\n      DB_NAME: ${DB_NAME:-artel}\n      DB_USERNAME: ${DB_USERNAME:-artel}\n      DB_PASSWORD: ${DB_PASSWORD}\n      DB_SSL_MODE: disable\n      REDIS_URL: redis://redis:6379\n      ARTEL_INTERNAL_API_PORT: \"8081\"\n      # The agent server serves every route under /internal, and the clients append /extract, /embed,\n      # /sessions and so on to this base URL, so the prefix belongs here.\n      ARTEL_AGENT_BASE_URL: http://agent-server:8000/internal\n      ARTEL_AGENT_WS_BASE_URL: ws://agent-server:8000/internal\n      # The server's application.yml sets org.springframework.web to DEBUG, which logs a line for every\n      # request including each 401, 403 and 404. Keep production logs at INFO.\n      LOGGING_LEVEL_ORG_SPRINGFRAMEWORK_WEB: INFO\n      LOGGING_LEVEL_ORG_SPRINGFRAMEWORK_WEB_REACTIVE: INFO\n      ARTEL_HOME_URL: ${ARTEL_PUBLIC_URL:-http://localhost:8088}\n      ARTEL_ALLOWED_ORIGINS: ${ARTEL_PUBLIC_URL:-http://localhost:8088},${ARTEL_ADMIN_URL:-http://localhost:8090}\n      ARTEL_JWT_SECRET: ${ARTEL_JWT_SECRET:?set ARTEL_JWT_SECRET in .env}\n      ARTEL_SECRETS_KEY: ${ARTEL_SECRETS_KEY:?set ARTEL_SECRETS_KEY in .env}\n      ARTEL_SECURE_COOKIE: ${ARTEL_SECURE_COOKIE:-false}\n      ARTEL_SIGNUP_OPEN: ${ARTEL_SIGNUP_OPEN:-false}\n      ARTEL_GITHUB_SIGNUP_OPEN: ${ARTEL_GITHUB_SIGNUP_OPEN:-false}\n      ARTEL_LOGIN_MAX_FAILURES: ${ARTEL_LOGIN_MAX_FAILURES:-10}\n      ARTEL_LOGIN_FAILURE_WINDOW: ${ARTEL_LOGIN_FAILURE_WINDOW:-PT15M}\n      ARTEL_LOGIN_ADDRESS_MAX_FAILURES: ${ARTEL_LOGIN_ADDRESS_MAX_FAILURES:-100}\n      OPENROUTER_API_KEY: ${OPENROUTER_API_KEY:-}\n      GITHUB_CLIENT_ID: ${GITHUB_CLIENT_ID:-}\n      GITHUB_CLIENT_SECRET: ${GITHUB_CLIENT_SECRET:-}\n      ARTEL_S3_BUCKET: ${ARTEL_S3_BUCKET:-artel}\n      ARTEL_S3_REGION: ${ARTEL_S3_REGION:-us-east-1}\n      # The server's own S3 calls go to MinIO over the compose network. Presigned URLs that the browser\n      # opens are written for the public origin, and the proxy forwards /<bucket>/ to MinIO unchanged.\n      # Credentials are always set here, so URLs are SigV4 presigned (never the anonymous objectUrl form).\n      ARTEL_S3_ENDPOINT: http://minio:9000\n      ARTEL_S3_PRESIGN_ENDPOINT: ${ARTEL_PUBLIC_URL:-http://localhost:8088}\n      ARTEL_S3_ACCESS_KEY: ${ARTEL_S3_ACCESS_KEY}\n      ARTEL_S3_SECRET_KEY: ${ARTEL_S3_SECRET_KEY}\n    # 8080 is reached only through the reverse proxy and 8081 only from this network.\n    # Neither is published to the host.\n    expose:\n      - \"8080\"\n      - \"8081\"\n\n  agent-server:\n    <<: *restart\n    image: ${ARTEL_AGENT_IMAGE:-ghcr.io/project-artel/agent:develop}\n    build:\n      context: ../artel-agent-server\n      target: runtime\n    environment:\n      APP_PORT: \"8000\"\n      APP_ENV: production\n      # The key comes from orchestration's admin setting first; this variable is the fallback.\n      OPENROUTER_API_KEY: ${OPENROUTER_API_KEY:-}\n      # Internal port: the unauthenticated /internal/** API. Reached only over the compose network.\n      ORCHESTRATION_BASE_URL: http://orchestration:8081\n      LANGSMITH_TRACING: \"false\"\n      # Optional. Nothing in a default install calls Bedrock.\n      BEDROCK_API_KEY: ${BEDROCK_API_KEY:-}\n    expose:\n      - \"8000\"\n\n  admin-page:\n    <<: *restart\n    image: ${ARTEL_ADMIN_IMAGE:-ghcr.io/project-artel/admin:main}\n    environment:\n      # The container replaces a placeholder in the bundle with these at start and exits if one is missing.\n      # The admin browser calls its own origin; the proxy forwards /api, /oauth2, /login/oauth2 and /ws.\n      VITE_ORCHESTRATION_URL: ${ARTEL_ADMIN_URL:-http://localhost:8090}\n      VITE_HOME_URL: ${ARTEL_PUBLIC_URL:-http://localhost:8088}\n    expose:\n      - \"8080\"\n\n  artel-home:\n    <<: *restart\n    image: ${ARTEL_CONSOLE_IMAGE:-ghcr.io/project-artel/console:develop}\n    environment:\n      VITE_ORCHESTRATION_URL: ${ARTEL_PUBLIC_URL:-http://localhost:8088}\n    expose:\n      - \"8080\"\n\n  proxy:\n    <<: *restart\n    image: caddy:2-alpine\n    depends_on:\n      - orchestration\n      - admin-page\n      - artel-home\n    configs:\n      - source: caddyfile\n        target: /etc/caddy/Caddyfile\n    volumes:\n      - caddy-data:/data\n      - caddy-config:/config\n    ports:\n      - \"${ARTEL_HTTP_PORT:-8088}:80\"\n      - \"${ARTEL_HTTPS_PORT:-8443}:443\"\n      - \"${ARTEL_ADMIN_PORT:-8090}:8090\"\n\n# Caddy configuration. Compose fills in the ${...} values from .env. Two origins, because each frontend\n# image serves its bundle from the root path, and each browser talks only to its own origin (no CORS).\n# The orchestration internal port 8081 is deliberately not routed.\nconfigs:\n  caddyfile:\n    content: |\n      ${ARTEL_SITE_ADDRESS:-:80} {\n        encode zstd gzip\n\n        # Presigned upload and download URLs go straight to MinIO. They are signed over the exact path\n        # and Host header, so this route must not rewrite either.\n        handle /${ARTEL_S3_BUCKET:-artel}/* {\n          reverse_proxy minio:9000\n        }\n\n        @orchestration path /api/* /oauth2/* /login/oauth2/* /ws/*\n        handle @orchestration {\n          # flush_interval -1 keeps server-sent event streams from being buffered.\n          reverse_proxy orchestration:8080 {\n            flush_interval -1\n          }\n        }\n\n        handle {\n          reverse_proxy artel-home:8080\n        }\n      }\n\n      ${ARTEL_ADMIN_SITE_ADDRESS:-:8090} {\n        encode zstd gzip\n\n        @orchestration path /api/* /oauth2/* /login/oauth2/* /ws/*\n        handle @orchestration {\n          reverse_proxy orchestration:8080 {\n            flush_interval -1\n          }\n        }\n\n        handle {\n          reverse_proxy admin-page:8080\n        }\n      }\n\nvolumes:\n  postgres-data:\n  minio-data:\n  caddy-data:\n  caddy-config:"
